import SwiftUI
import AuthenticationServices
@MainActor final class AppStore:ObservableObject {
 @Published var configuration:AppConfiguration?;@Published var events:[FightEvent]=[];@Published var event:FightEvent?;@Published var picks=PickSelection();@Published var groups:[ParlayGroup]=[];@Published var cards:[CreatorCard]=[];@Published var profile:Profile?;@Published var savedTickets:[SavedTicket]=[];@Published var savedDrafts:[SavedDraft]=[];@Published var message:String?;@Published var busy=false;@Published var tab=0;@Published var session:AuthSession?=SessionVault.read();@Published var showLogin=false;@Published var showPoster=false
 var revisions:[String:Int]=[:];var feedNext:String?;private var refreshTask:Task<AuthSession,Error>?;private var authGeneration=0
 var signedIn:Bool{session != nil};var owner:String{session?.user?.id ?? "guest"}
 func run(_ work:@escaping @MainActor () async throws -> Void){Task{do{try await work()}catch{self.message=error.localizedDescription}}}
 func start() async {do{configuration=try await APIClient.request("config");let r:EventsResponse=try await APIClient.request("events");events=r.events;let next=events.first{!($0.completed ?? false)&&($0.startTime.flatMap{ISO8601DateFormatter().date(from:$0)} ?? .distantFuture)>Date().addingTimeInterval(-86400)} ?? events.last;if let next{try await selectEvent(next.id)};if signedIn{try await loadAccount()}}catch{message=error.localizedDescription}}
 func token() async throws -> String? {
  guard let s=session else{return nil};guard let c=configuration?.auth else{throw APIError(message:"OnlyFights sign-in is not connected yet.",status:503)}
  if (s.expires_at ?? 0)>Date().timeIntervalSince1970+60{return s.access_token}
  if let refreshTask{return try await refreshTask.value.access_token}
  let generation=authGeneration;let task=Task{try await AuthService.call(c,path:"token?grant_type=refresh_token",body:["refresh_token":s.refresh_token]) as AuthSession};refreshTask=task
  defer{refreshTask=nil};do{let result=try await task.value;guard generation==authGeneration else{throw CancellationError()};try setSession(result);return result.access_token}catch{throw APIError(message:"Sign in again to sync. Your local picks are still here.",status:401)}
 }
 func selectEvent(_ id:String) async throws {persistLocal();let r:EventResponse=try await APIClient.request("events/"+id);event=r.event;picks=PickSelection();if let data=UserDefaults.standard.data(forKey:"picks.\(owner).\(id)"),let p=try? JSONDecoder().decode(PickSelection.self,from:data){picks=p};reconcile();groups=[]}
 func reconcile(){guard let event else{return};picks.values=picks.values.filter{key,p in event.fights.contains{f in f.id==key&&f.fighters.contains{$0.id==p.athleteId}&&f.fighters.contains{$0.id==p.opponentId}}}}
 func persistLocal(){guard let e=event,let data=try? JSONEncoder().encode(picks) else{return};UserDefaults.standard.set(data,forKey:"picks.\(owner).\(e.id)")}
 func choose(_ f:Fight,_ a:Fighter){guard let other=f.fighters.first(where:{$0.id != a.id}) else{return};picks.choose(fightID:f.id,athleteID:a.id,opponentID:other.id);persistLocal()}
 func payload()->PickPayload?{guard let e=event else{return nil};var p=PickPayload(event:e,picks:picks,revision:revisions[e.id] ?? 0);p.picks=p.picks.map{record in var r=record;if let f=e.fights.first(where:{$0.id==r.fightId}),let a=f.fighters.first(where:{$0.id==r.athleteId}),let b=f.fighters.first(where:{$0.id==r.opponentId}){r.fighter=a.name;r.opponent=b.name;r.photo=a.photo;r.opponentPhoto=b.photo;r.segment=f.segment;r.posterSide=f.fighters.firstIndex(where:{$0.id==a.id})};return r};return p}
 func saveCloud() async throws {guard signedIn else{persistLocal();showLogin=true;return};guard let p=payload() else{return};let r:ActionResponse=try await APIClient.request("drafts/"+p.event,method:"PUT",body:JSONEncoder().encode(p),token:token());revisions[p.event]=r.revision;message="Picks saved to your account."}
 func loadCloud() async throws {guard signedIn else{showLogin=true;return};guard let e=event else{return};let r:DraftResponse=try await APIClient.request("drafts/"+e.id,token:token());revisions[e.id]=r.revision;guard let draft=r.draft else{message="No cloud save for this event yet.";return};picks.values=Dictionary(uniqueKeysWithValues:draft.picks.map{($0.fightId,$0)});reconcile();persistLocal();message="Saved picks loaded."}
 func createParlays() async throws {guard let p=payload() else{return};busy=true;defer{busy=false};let r:GroupsResponse=try await APIClient.request("recommendations",method:"POST",body:JSONEncoder().encode(p));groups=r.groups;tab=1;if groups.isEmpty{message="Choose at least two fighters with posted moneylines."}}
 func saveTicket(_ t:ParlayTicket) async throws {guard signedIn else{showLogin=true;return};guard let e=event else{return};struct TicketBody:Encodable{var event:String;var category:String;var legs:[TicketLeg]};let _:ActionResponse=try await APIClient.request("tickets",method:"POST",body:JSONEncoder().encode(TicketBody(event:e.id,category:t.category,legs:t.legs)),token:token());try await loadAccount();message="Ticket saved. No wager placed."}
 func loadFeed(following:Bool=false,more:Bool=false) async throws {let path="feed?following=\(following ? 1:0)"+(more ? "&before="+(feedNext?.addingPercentEncoding(withAllowedCharacters:.urlQueryAllowed) ?? "") : "");let r:FeedResponse=try await APIClient.request(path,token:token());cards=more ? cards+r.cards:r.cards;feedNext=r.next}
 func tail(_ card:CreatorCard,replace:Bool) async throws {guard signedIn else{showLogin=true;return};if !replace,event?.id==card.event,!picks.values.isEmpty{throw APIError(message:"You have device picks. Choose Replace & tail to replace them.",status:409)};let d:DraftResponse=try await APIClient.request("drafts/"+card.event,token:token());if d.draft != nil && !replace{throw APIError(message:"You already have saved picks. Use Replace & tail to replace them.",status:409)};struct Tail:Encodable{var replace:Bool;var revision:Int};let _:ActionResponse=try await APIClient.request("shares/"+card.id+"/tail",method:"POST",body:JSONEncoder().encode(Tail(replace:replace,revision:d.revision)),token:token());try await selectEvent(card.event);try await loadCloud();tab=0}
 func creatorAction(_ type:String,_ username:String,remove:Bool=false) async throws {guard signedIn else{showLogin=true;return};let _:ActionResponse=try await APIClient.request(type+"/"+username,method:remove ? "DELETE":"PUT",body:Data("{}".utf8),token:token());message=type=="blocks" ? "Creator blocked.":remove ? "Unfollowed.":"Following @\(username).";if type=="blocks"{cards.removeAll{$0.username==username}}}
 func report(_ card:CreatorCard,reason:String) async throws {guard signedIn else{showLogin=true;return};let _:ActionResponse=try await APIClient.request("reports",method:"POST",body:JSONSerialization.data(withJSONObject:["shareId":card.id,"reason":reason]),token:token());message="Report received for review."}
 func publish() async throws -> CreatorCard {guard signedIn else{showLogin=true;throw APIError(message:"Sign in to publish your card.",status:401)};guard let p=payload() else{throw APIError(message:"Choose your fighters first.",status:400)};return try await APIClient.request("shares",method:"POST",body:JSONEncoder().encode(p),token:token())}
 func loadAccount() async throws {let r:AccountResponse=try await APIClient.request("me",token:token());profile=r.profile;savedDrafts=r.drafts;savedTickets=r.tickets}
 func username(_ value:String) async throws {let _:ActionResponse=try await APIClient.request("profile",method:"POST",body:JSONSerialization.data(withJSONObject:["username":value]),token:token());try await loadAccount()}
 func emailCode(_ email:String) async throws {guard let c=configuration?.auth else{throw APIError(message:"Apple/email sign-in is waiting for the app owner's setup.",status:503)};struct Empty:Decodable{};let _:Empty=try await AuthService.call(c,path:"otp",body:["email":email]);message="Check your email for the sign-in code."}
 func verifyCode(email:String,code:String) async throws {guard let c=configuration?.auth else{return};let s:AuthSession=try await AuthService.call(c,path:"verify",body:["email":email,"token":code,"type":"email"]);try setSession(s);showLogin=false;try await loadAccount()}
 func apple(idToken:String,nonce:String) async throws {guard let c=configuration?.auth else{throw APIError(message:"Apple sign-in is not connected yet.",status:503)};let s:AuthSession=try await AuthService.call(c,path:"token?grant_type=id_token",body:["provider":"apple","id_token":idToken,"nonce":nonce]);try setSession(s);showLogin=false;try await loadAccount()}
 func setSession(_ value:AuthSession) throws {if session?.user?.id != value.user?.id{authGeneration+=1;revisions=[:]};var s=value;if s.expires_at==nil{s.expires_at=Date().timeIntervalSince1970+(s.expires_in ?? 3600)};try SessionVault.save(s);session=s}
 func signOut(){authGeneration+=1;refreshTask?.cancel();refreshTask=nil;let id=owner;for key in UserDefaults.standard.dictionaryRepresentation().keys where key.hasPrefix("picks.\(id).") {UserDefaults.standard.removeObject(forKey:key)};try? SessionVault.save(nil);session=nil;profile=nil;savedTickets=[];savedDrafts=[];revisions=[:];picks=PickSelection();groups=[];cards=[];message="Signed out on this device."}
 func deleteAccount() async throws {let _:ActionResponse=try await APIClient.request("account",method:"DELETE",body:Data("{\"confirm\":\"DELETE\"}".utf8),token:token());signOut();message="Account deleted."}
 func openShared(_ url:URL) {guard let c=URLComponents(url:url,resolvingAgainstBaseURL:false),url.scheme=="onlyfights"||url.host==APIClient.base.host,let id=c.queryItems?.first(where:{$0.name=="betaShare"})?.value,id.range(of:"^[A-Za-z0-9_-]{12,40}$",options:.regularExpression) != nil else{return};run{let card:CreatorCard=try await APIClient.request("shares/"+id,token:self.token());self.cards=[card];self.tab=2}}
}
